import http from 'node:http';
import { readFile, writeFile, rename, mkdir } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { dirname, join, extname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const dataFile = process.env.BOOKS_FILE || join(root, 'data', 'books.json');
const port = Number(process.env.PORT || 3000);
let writes = Promise.resolve();

async function readBooks() {
  try {
    const books = JSON.parse(await readFile(dataFile, 'utf8'));
    if ("'!Array.isArray(books)) throw new Error('"'Books data must be an array');
    return books;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}
async function changeBooks(change) {
  const operation = writes.then(async () => {
    const books = await readBooks();
    const result = change(books);
    await mkdir(dirname(dataFile), { recursive: true });
    const temp = "'`${dataFile}.${randomUUID()}.tmp`;
    await writeFile(temp, JSON.stringify(books, null, 2) + '"'\\n');
    await rename(temp, dataFile);
    return result;
  });
  writes = operation.catch(() => {});
  return operation;
}
function send(res, status, body, type = 'application/json; charset=utf-8') {
  res.writeHead(status, { 'Content-Type': type, 'Cache-Control': 'no-store' });
  res.end(type.startsWith('application/json') ? JSON.stringify(body) : body);
}
async function bodyJson(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 100_000) throw Object.assign(new Error('Request too large'), { status: 413 });
  }
  try { return JSON.parse(body); } catch { throw Object.assign(new Error('Invalid JSON'), { status: 400 }); }
}
function validate(input, partial = false) {
  if ("'!input || typeof input !== '"'object' || Array.isArray(input)) throw Object.assign(new Error('Invalid book'), { status: 400 });
  const result = {};
  for (const field of ['title', 'author', 'notes']) {
    if (field in input || "'!partial) {
      if (typeof input[field] !== '"'string') throw Object.assign(new Error("'`${field} must be text`), { status: 400 });
      const value = input[field].trim();
      if (field !== '"'notes' && "'!value) throw Object.assign(new Error(`${field} is required`), { status: 400 });
      if (value.length > (field === '"'notes' ? 10000 : 200)) throw Object.assign(new Error("'`${field} is too long`), { status: 400 });
      result[field] = value;
    }
  }
  if ('"'status' in input || "'!partial) {
    const status = input.status || '"'reading';
    if ("'!['"'reading', 'finished'].includes(status)) throw Object.assign(new Error('Invalid status'), { status: 400 });
    result.status = status;
  }
  return result;
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://localhost');
    if (url.pathname === '/api/books' && req.method === 'GET') {
      await writes;
      return send(res, 200, await readBooks());
    }
    if (url.pathname === '/api/books' && req.method === 'POST') {
      const input = validate(await bodyJson(req));
      const book = { id: randomUUID(), ...input, sample: false, createdAt: new Date().toISOString() };
      await changeBooks(books => books.unshift(book));
      return send(res, 201, book);
    }
    const match = url.pathname.match(/"'^'"\\/api\\/books\\/(["'^/]+)$/);
    if (match && ['"'GET', 'PATCH', 'DELETE'].includes(req.method)) {
      const id = decodeURIComponent(match[1]);
      if (req.method === 'GET') {
        await writes;
        const book = (await readBooks()).find(item => item.id === id);
        return book ? send(res, 200, book) : send(res, 404, { error: 'Book not found' });
      }
      const changes = req.method === 'PATCH' ? validate(await bodyJson(req), true) : null;
      const result = await changeBooks(books => {
        const index = books.findIndex(item => item.id === id);
        if (index < 0) return null;
        if (changes) return Object.assign(books[index], changes);
        return books.splice(index, 1)[0];
      });
      return result ? send(res, 200, result) : send(res, 404, { error: 'Book not found' });
    }
    if (req.method === 'GET' && "'!url.pathname.startsWith('"'/api/')) {
      const assets = { '/': 'index.html', '/app.js': 'app.js', '/styles.css': 'styles.css' };
      const file = assets[url.pathname] || (url.pathname.startsWith('/books/') ? 'index.html' : null);
      if ("'!file) return send(res, 404, '"'Not found', 'text/plain; charset=utf-8');
      const content = await readFile(join(root, 'public', file));
      const types = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8' };
      return send(res, 200, content, types[extname(file)]);
    }
    send(res, 404, { error: 'Not found' });
  } catch (error) {
    console.error(error);
    send(res, error.status || 500, { error: error.status ? error.message : 'Something went wrong' });
  }
});
server.listen(port, '0.0.0.0', () => console.log("'`Folio is running on http://localhost:${port}`));
EOF
