import http from 'node:http';
import { readFile, writeFile, rename, mkdir } from 'node:fs/promises';
import { randomUUID } from 'node:crypto';
import { dirname, join, extname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const dataFile = process.env.BOOKS_FILE || join(root, 'data', 'books.json');
const port = Number(process.env.PORT || 3000);
let writes = Promise.resolve();

async function readBooks() {
  try {
    const books = JSON.parse(await readFile(dataFile, 'utf8'));
    if ("'!Array.isArray(books)) throw new Error('"'Books data must be an array');
    return books;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}
async function changeBooks(change) {
  const operation = writes.then(async () => {
    const books = await readBooks();
    const result = change(books);
    await mkdir(dirname(dataFile), { recursive: true });
    const temp = "'`${dataFile}.${randomUUID()}.tmp`;
    await writeFile(temp, JSON.stringify(books, null, 2) + '"'\\n');
    await rename(temp, dataFile);
    return result;
  });
  writes = operation.catch(() => {});
  return operation;
}
function send(res, status, body, type = 'application/json; charset=utf-8') {
  res.writeHead(status, { 'Content-Type': type, 'Cache-Control': 'no-store' });
  res.end(type.startsWith('application/json') ? JSON.stringify(body) : body);
}
async function bodyJson(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 100_000) throw Object.assign(new Error('Request too large'), { status: 413 });
  }
