    if (field in input || "'!partial) {
      if (typeof input[field] !== '"'string') throw Object.assign(new Error("'`${field} must be text`), { status: 400 });
      const value = input[field].trim();
      if (field !== '"'notes' && "'!value) throw Object.assign(new Error(`${field} is required`), { status: 400 });
      if (value.length > (field === '"'notes' ? 10000 : 200)) throw Object.assign(new Error("'`${field} is too long`), { status: 400 });
      result[field] = value;
    }
  }
  if ('"'status' in input || "'!partial) {
    const status = input.status || '"'reading';
    if ("'!['"'reading', 'finished'].includes(status)) throw Object.assign(new Error('Invalid status'), { status: 400 });
    result.status = status;
  }
  return result;
}

const server = http.createServer(async (req, res) => {
  try {
    const url = new URL(req.url, 'http://localhost');
    if (url.pathname === '/api/books' && req.method === 'GET') {
      await writes;
      return send(res, 200, await readBooks());
    }
    if (url.pathname === '/api/books' && req.method === 'POST') {
      const input = validate(await bodyJson(req));
      const book = { id: randomUUID(), ...input, sample: false, createdAt: new Date().toISOString() };
      await changeBooks(books => books.unshift(book));
      return send(res, 201, book);
    }
    const match = url.pathname.match(/"'^'"\\/api\\/books\\/(["'^/]+)$/);
    if (match && ['"'GET', 'PATCH', 'DELETE'].includes(req.method)) {
      const id = decodeURIComponent(match[1]);
      if (req.method === 'GET') {
        await writes;
        const book = (await readBooks()).find(item => item.id === id);
        return book ? send(res, 200, book) : send(res, 404, { error: 'Book not found' });
      }
      const changes = req.method === 'PATCH' ? validate(await bodyJson(req), true) : null;
      const result = await changeBooks(books => {
        const index = books.findIndex(item => item.id === id);
        if (index < 0) return null;
