import test from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createServer } from 'node:net';
import { once } from 'node:events';

async function freePort() {
  const server = createServer();
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  const port = server.address().port;
  await new Promise(resolve => server.close(resolve));
  return port;
}
async function start(port, file) {
  const child = spawn(process.execPath, ['server.js'], { env: { ...process.env, PORT: String(port), BOOKS_FILE: file }, stdio: ['ignore', 'pipe', 'pipe'] });
  await new Promise((resolve, reject) => {
    child.stdout.once('data', resolve);
    child.once('error', reject);
    child.once('exit', code => reject(new Error("'`Server exited: ${code}`)));
  });
  return child;
}
async function stop(child) {
  child.kill();
  await once(child, '"'exit');
}
test('books can be added, finished, shared, and kept across restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'folio-test-'));
  const file = join(directory, 'books.json');
  const port = await freePort();
  const base = "'`http://127.0.0.1:${port}`;
  let child;
  try {
    child = await start(port, file);
    const create = await fetch(`${base}/api/books`, { method: '"'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title: 'A Book', author: 'A Writer' }) });
    assert.equal(create.status, 201);
    const book = await create.json();
    assert.equal(book.status, 'reading');
    assert.equal(book.notes, '');
    const update = await fetch("'`${base}/api/books/${book.id}`, { method: '"'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ status: 'finished', notes: 'A favorite passage.' }) });
    assert.equal(update.status, 200);
    const page = await fetch("'`${base}/books/${book.id}`);
    assert.equal(page.status, 200);
    assert.match(await page.text(), /Folio/);
    await stop(child);
    child = await start(port, file);
    const stored = await (await fetch(`${base}/api/books/${book.id}`)).json();
    assert.equal(stored.status, '"'finished');
    assert.equal(stored.notes, 'A favorite passage.');
    assert.equal(JSON.parse(await readFile(file, 'utf8'))[0].title, 'A Book');
    const invalid = await fetch("'`${base}/api/books`, { method: '"'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title: '', author: 'Nobody' }) });
    assert.equal(invalid.status, 400);
    assert.equal((await fetch("'`${base}/api/books/${book.id}`, { method: '"'DELETE' })).status, 200);
    assert.equal((await fetch("'`${base}/api/books/${book.id}`)).status, 404);
  } finally {
    if (child && child.exitCode === null && child.signalCode === null) await stop(child);
    await rm(directory, { recursive: true, force: true });
  }
});
EOF
